DECLARE @StatusMessage NVARCHAR(MAX) = '';
DECLARE @bodyMessage NVARCHAR(MAX);
DECLARE @subject NVARCHAR(MAX);

SELECT @StatusMessage = @StatusMessage + 

    JobName + ': ' + step_name + ': ' + StepStatus + CHAR(13) + CHAR(10) + message + CHAR(13) + CHAR(10)

FROM (

    SELECT TOP 3 

        j.name AS JobName,

        s.step_name,

        CASE h.run_status

            WHEN 0 THEN 'Failed'

            WHEN 1 THEN 'Succeeded'

            WHEN 2 THEN 'Retry'

            WHEN 3 THEN 'Canceled'

            WHEN 4 THEN 'In Progress'

            ELSE 'Unknown'

        END AS StepStatus,

        h.message

    FROM msdb.dbo.sysjobhistory h

    INNER JOIN msdb.dbo.sysjobs j ON h.job_id = j.job_id

    INNER JOIN msdb.dbo.sysjobsteps s ON h.job_id = s.job_id AND h.step_id = s.step_id

    WHERE h.step_id > 0

      AND j.name = 'P4W HANA - Cost and Variance Analysis Reports'

      AND h.run_date = (SELECT MAX(run_date) FROM msdb.dbo.sysjobhistory WHERE job_id = j.job_id)

    ORDER BY j.name, h.run_date DESC, h.run_time DESC

) A;

SELECT @StatusMessage AS FinalMessage;


 IF (@StatusMessage LIKE '%Fail%') OR (@StatusMessage LIKE '%Cancel%')
    SET @Subject = 'Job Failure Alert: P4W HANA - Cost and Variance Analysis Reports';
ELSE
    SET @Subject = 'Job Success Notification: P4W HANA - Cost and Variance Analysis Reports';
 
-- Send the email

SET @bodyMessage = ISNULL(@StatusMessage, '') + CHAR(13) + CHAR(10) + 'Job execution completed';

EXEC msdb.dbo.sp_send_dbmail
    @profile_name = 'Day3ActivityMail',
    @recipients = 'DL_MS_Reporting@carestream.com',
    @subject = @Subject,
    @body = @bodyMessage;
